package org.apache.dubbo.common.utils;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Method;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;
import java.util.concurrent.CompletableFuture;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ReflectUtilsGetReturnTypesTest {

    interface GenericFutureService<T> {
        CompletableFuture<T> getGenericFuture();
    }

    @Test
    void shouldResolveTypeVariableReturnTypeForGenericFuture() throws Exception {
        Method method = GenericFutureService.class.getMethod("getGenericFuture");

        Type[] returnTypes = ReflectUtils.getReturnTypes(method);

        assertEquals(2, returnTypes.length);
        assertEquals(Object.class, returnTypes[0], "Raw return type should resolve to Object for unbounded type variable");
        assertTrue(returnTypes[1] instanceof TypeVariable, "Generic return type should remain a TypeVariable");

        TypeVariable<?> typeVariable = (TypeVariable<?>) returnTypes[1];
        assertEquals("T", typeVariable.getName());
        assertEquals(
                ((TypeVariable<?>) ((java.lang.reflect.ParameterizedType) method.getGenericReturnType())
                        .getActualTypeArguments()[0]).getName(),
                typeVariable.getName()
        );
    }
}

